<script>
/* Shared by the card and standalone previews. Preview mode is explicit. */
(function () {
  'use strict';
  function host(name) {
    try { if (window[name]) return window[name]; } catch (_) {}
    try { return window.parent && window.parent[name]; } catch (_) { return null; }
  }
  window.QBCC = {
    host: host,
    mvu: function () { return host('Mvu'); },
    ready: async function () {
      for (var i = 0; i < 40; i++) {
        var m = host('Mvu'); if (m) return m;
        await new Promise(function (r) { setTimeout(r, 100); });
      }
      throw new Error('MVU chưa sẵn sàng. Bật MVU và cấu trúc biến trong Tavern Helper, rồi thử lưu lại.');
    },
    download: function (value, name) {
      var blob = new Blob([JSON.stringify(value, null, 2)], {type: 'application/json'});
      var url = URL.createObjectURL(blob), a = document.createElement('a');
      a.href = url; a.download = name; a.click();
      setTimeout(function () { URL.revokeObjectURL(url); }, 2000);
    }
  };
  if (!window.QBCC_PREVIEW) return;
  var memory = null, listeners = [];
  try { memory = JSON.parse(localStorage.getItem('qbcc_preview_profile_v2') || 'null'); } catch (_) {}
  window.Mvu = {
    events: {VARIABLE_UPDATE_ENDED: 'qbcc-preview-update'},
    getMvuData: function () { return {stat_data: memory ? JSON.parse(JSON.stringify(memory)) : null}; },
    replaceMvuData: async function (data) {
      memory = JSON.parse(JSON.stringify(data.stat_data));
      try { localStorage.setItem('qbcc_preview_profile_v2', JSON.stringify(memory)); }
      catch (_) { document.getElementById('previewNote').textContent = 'Đã lưu trong phiên này. Trình duyệt chặn lưu lâu dài; hãy xuất hồ sơ JSON trước khi đóng.'; }
      listeners.forEach(function (fn) { fn(); });
    }
  };
  window.getCurrentMessageId = function () { return 0; };
  window.eventOn = function (_, fn) { listeners.push(fn); };
  window.addEventListener('storage', function (e) {
    if (e.key === 'qbcc_preview_profile_v2') {
      try { memory = JSON.parse(e.newValue); listeners.forEach(function (fn) { fn(); }); } catch (_) {}
    }
  });
  document.addEventListener('DOMContentLoaded', function () {
    var panel = document.createElement('div'); panel.className = 'preview-tools';
    panel.innerHTML = '<b>' + (document.getElementById('wizard') ? 'BẢNG TẠO NHÂN VẬT' : 'BẢNG TRẠNG THÁI') + '</b><p id="previewNote">Hồ sơ lưu trên trình duyệt này. Chưa kết nối AI; có thể xuất JSON để giữ hoặc chuyển hồ sơ.</p><div><a href="lorebook.html">Đọc lorebook</a> <button id="previewExport">Xuất hồ sơ</button> <label class="file-label">Nhập hồ sơ<input id="previewImport" type="file" accept=".json,application/json" hidden></label> <button id="previewSample">Xem nhân vật mẫu</button></div>';
    document.body.prepend(panel);
    if(document.getElementById('exportState'))document.getElementById('previewExport').style.display='none';
    var style = document.createElement('style');
    style.textContent = '.preview-tools{max-width:980px;margin:0 auto 16px;padding:14px;border:1px solid #6e5937;border-radius:12px;background:#171b22;color:#e9e4d8;font:15px/1.5 "Segoe UI",Tahoma,Arial,sans-serif}.preview-tools p{color:#bbb5a9;margin:5px 0 10px}.preview-tools a,.preview-tools button,.file-label{display:inline-block;padding:6px 10px;margin:3px;border:1px solid #78623e;border-radius:6px;background:#20252e;color:#e6cf99;cursor:pointer;text-decoration:none;font:inherit}body{min-height:100vh}';
    document.head.appendChild(style);
    var note = document.getElementById('previewNote');
    document.getElementById('previewExport').onclick = function () {
      if (!memory) { note.textContent = 'Hãy tạo nhân vật hoặc mở nhân vật mẫu trước khi xuất.'; return; }
      window.QBCC.download(memory, 'QBCC_ho_so.json');
    };
    document.getElementById('previewImport').onchange = async function (event) {
      try {
        var file = event.target.files[0]; if (!file) return;
        if (file.size > 2000000) throw new Error('Hồ sơ vượt quá 2 MB.');
        var text = await file.text();
        var data = JSON.parse(text, function (k, v) {
          if (['__proto__', 'constructor', 'prototype'].indexOf(k) >= 0) throw new Error('Khóa dữ liệu không hợp lệ.');
          return v;
        });
        if (data.stat_data) data = data.stat_data;
