Werewolf","狼人","Xác Sống","Hoạt Thi","Zombie","活尸","Oán Hồn","Wraith","怨魂","Con Rối Gỗ","Mộc Ngẫu","Puppet","木偶","Môn Đồ Trầm Mặc","Disciple of Silence","沉默门徒","Tà Vật Cổ Đại","Ancient Bane","古代邪物","Thần Nghiệt","Abomination","神孽","Kẻ Bị Trói"],"seq":[["Tù Nhân","Tù Phạm","Prisoner","囚犯","Giỏi thoát khỏi trói buộc, cơ thể dẻo, chịu đựng tốt – nhưng tinh thần như bị giam cầm, khao khát 'phá ngục'."],["Kẻ Điên","Phong Tử","Lunatic","疯子","Sức mạnh khi mất kiểm soát cảm xúc, gây hoảng loạn; tam quan dễ vặn vẹo."],["Người Sói","Lang Nhân","Werewolf","狼人","Hóa sói: móng vuốt, sức mạnh, hồi phục, nguyền rủa lây nhiễm."],["Xác Sống","Hoạt Thi","Zombie","活尸","Cơ thể xác sống: gần như không cảm thấy đau, bền bỉ, băng giá (ví dụ Maric)."],["Oán Hồn","Oán Hồn","Wraith","怨魂","Thể linh hồn: xuyên vật, nhập thân, tiếng thét tinh thần (ví dụ Sharron)."],["Con Rối Gỗ","Mộc Ngẫu","Puppet","木偶","Bán thần. Cơ thể như con rối, thế thân."],["Môn Đồ Trầm Mặc","Trầm Mặc Môn Đồ (cổ: Nguyền Rủa Chi Vật)","Disciple of Silence","沉默门徒","Nguyền rủa biến hình."],["Tà Vật Cổ Đại","Cổ Đại Tà Vật","Ancient Bane","古代邪物","Thiên sứ. Lời nguyền biến hình gần như vĩnh viễn."],["Thần Nghiệt","Thần Nghiệt","Abomination","神孽","Thiên sứ cấp cao."],["Kẻ Bị Trói Buộc","Bị Phược Giả","Chained","被缚者","Chân thần."]],"sam_vai":"Tù Nhân: 'kìm nén' bản thân, tự trói buộc dục vọng. Kẻ Điên: điên nhưng có kiểm soát. Người Sói: kiềm chế dã tính."},{"id":"banh_xe","ten":"Bánh Xe Vận Mệnh","hv":"Mệnh Vận Chi Luân","en":"Wheel of Fortune","cn":"命运之轮","nhom":"Quang Chi Thi (Bánh Xe Vận Mệnh – đơn độc)","mau":"#1abc9c","nam_giu":"Sinh Mệnh Học Phái (nắm khởi đầu Danh sách 9); Mạc Tư Khổ Tu Hội (một phần)","alias":["Bánh Xe Vận Mệnh","Mệnh Vận Chi Luân","Wheel of Fortune","命运之轮","Quái Vật","Monster","怪物","Cỗ Máy","Cơ Khí","Robot","机器","Kẻ May Mắn","Hạnh Vận Giả","Lucky One","幸运者","Giáo Sĩ Tai Họa","Calamity Priest","灾祸教士","Người Thắng Cuộc","Doanh Gia","Winner","赢家","Pháp Sư Vận Rủi","Misfortune Mage","厄运法师","Kẻ Du Hành Hỗn Loạn","Chaoswalker","混乱行者","Nhà Tiên Tri","Soothsayer","先知","Rắn Thủy Ngân","Rắn Vận Mệnh","Snake of Mercury","水银之蛇","命运之蛇"],"seq":[["Quái Vật","Quái Vật","Monster","怪物","Trực giác nhạy bén về nguy hiểm, linh cảm bẩm sinh; hay rơi vào trạng thái hoảng hốt, lẩm bẩm lời khó hiểu. (Có người sinh ra đã mang nửa đặc tính.)"],["Cỗ Máy","Cơ Khí","Robot","机器","Năng lực tính toán khủng khiếp, kiểm soát chính xác, thể chất tăng mạnh; bói toán và phản bói toán."],["Kẻ May Mắn","Hạnh Vận Giả","Lucky One","幸运者","Vận may kỳ lạ trong đời thường: ra đường nhặt được tiền, đạn né người, gieo xúc xắc như ý."],["Giáo Sĩ Tai Họa","Tai Họa Giáo Sĩ","Calamity Priest","灾祸教士","Dự cảm và dẫn dắt tai họa về phía kẻ khác."],["Người Thắng Cuộc","Doanh Gia","Winner","赢家","Tăng xác suất thắng lợi, 'thắng' trong cá cược với vận mệnh."],["Pháp Sư Vận Rủi","Ách Vận Pháp Sư","Misfortune Mage","厄运法师","Bán thần. Gieo vận rủi."],["Kẻ Du Hành Hỗn Loạn","Hỗn Loạn Hành Giả","Chaoswalker","混乱行者","Đi giữa hỗn loạn, xáo trộn vận mệnh."],["Nhà Tiên Tri","Tiên Tri","Soothsayer","先知","Thiên sứ."],["Rắn Thủy Ngân","Thủy Ngân Chi Xà / Mệnh Vận Chi Xà","Snake of Mercury","水银之蛇","Thiên sứ cấp cao – vd. Will Auceptin; 'khởi động lại' vận mệnh."],["Bánh Xe Vận Mệnh","Mệnh Vận Chi Luân","Wheel of Fortune","命运之轮","Chân thần."]],"sam_vai":"Quái Vật: cảm nhận 'vận mệnh' và nguy hiểm. Cỗ Máy: lý trí như cỗ máy tính toán. Kẻ May Mắn: đón nhận vận may nhưng không lạm dụng."},{"id":"vuc_tham","ten":"Vực Sâu","hv":"Thâm Uyên","en":"Abyss","cn":"深渊","nhom":"Bóng Tối Dị Loại (Kẻ Bị Trói – Vực Sâu)","mau":"#7b241c","nam_giu":"Bái Huyết Giáo (tôn thờ ác ma); các 'gia tộc ác ma'","alias":["Vực Sâu","Thâm Uyên","Abyss","深渊","Tội Phạm","Criminal","罪犯","Thiên Sứ Gãy Cánh","Chiết Dực Thiên Sứ","Lãnh Huyết Giả","Unwinged Angel","折翼天使","Sát Nhân Hàng Loạt","Liên Hoàn Sát Thủ","Serial Killer","连环杀手","Ác Ma","Devil","恶魔","Sứ Đồ Dục Vọng","Dục Vọng Sứ Đồ","Desire Apostle","欲望使徒","Ma Quỷ","Demon","魔鬼","Kẻ Nói Mê","Nghệ Ngữ Giả","呓语者","Quân Vương Ô Uế","Filthy Monarch","污秽君王"],"seq":[["Tội Phạm","Tội Phạm","Criminal","罪犯","Thân thể cường tráng, trực giác nhạy bén, đủ loại kỹ năng phạm tội – lương tri vẫn chưa mất."],["Thiên Sứ Gãy Cánh","Chiết Dực Thiên Sứ (cổ: Lãnh Huyết Giả)","Unwinged Angel","折翼天使","Mất lương tri, đồng lõa với ác dục, thân thể phi nhân hơn, có năng lực loại phép thuật của ác ma."],["Sát Nhân Hàng Loạt","Liên Hoàn Sát Thủ","Serial Killer","连环杀手","Nắm các nghi thức sùng bái, thủ đoạn giết người, ẩn nấp truy dấu."],["Ác Ma","Ác Ma","Devil","恶魔","Hỏa cầu lưu huỳnh, 'lời ô uế' làm chậm/ gây đau, dự cảm nguy hiểm; phi nhân hóa."],["Sứ Đồ Dục Vọng","Dục Vọng Sứ Đồ","Desire Apostle","欲望使徒","Thao túng và phóng đại dục vọng, 'kiếm dung nham', hóa thân bóng tối dục vọng."],["Ma Quỷ","Ma Quỷ","Demon","魔鬼","Bán thần."],["Kẻ Nói Mê","Nghệ Ngữ Giả","(Whisperer)","呓语者","Thì thầm ô uế."],["(Danh sách 2 – chưa rõ tên trong chính văn)","—","Bloody Archduke","—","Thiên sứ."],["Quân Vương Ô Uế","Ô Uế Quân Vương","Filthy Monarch","污秽君王","Thiên sứ cấp cao."],["Vực Sâu","Thâm Uyên","Abyss","深渊","Chân thần."]],"sam_vai":"Tội Phạm: phạm tội nhưng giữ lằn ranh cuối cùng. Thiên Sứ Gãy Cánh: buông bỏ lương tri (cực nguy hiểm cho nhân tính). Sát Nhân Hàng Loạt: nghi thức hóa việc giết chóc."}];
var PWX = {"ke_kho": {"cong_thuc": {"9": "Thầy Bói – Nguyên liệu chính: Tinh thủy tinh 50 g, máu bạch tuộc Lava 10 ml (phần phụ liệu: theo bản của giáo hội).", "8": "Chú Hề – Chính: 1 tinh thể sừng đơn của sơn dương xám Hornacis trưởng thành, 1 đóa Hoa hồng mặt người hoàn chỉnh. Phụ: nước tinh khiết 80 ml, 5 giọt nước ép cà độc dược, 7 g bột hoa hướng dương viền đen, 10 g bột cỏ áo choàng vàng, 3 giọt nước độc cần.", "7": "Ảo Thuật Gia – Chính: một khúc rễ thật của Thụ nhân sương mù, toàn bộ dịch tủy sống của Hắc báo tà văn. Phụ: nước tinh khiết 60 ml, dịch Thụ nhân sương mù 30 ml, 3 g bột ngọc thủy hình, 4 giọt tinh dầu cỏ ảo mộng.", "6": "Vô Diện Nhân – Chính: tuyến yên dị biến của Kẻ săn ngàn mặt (một loài rồng hiếm), đặc tính U ảnh da người. Phụ: máu Kẻ săn ngàn mặt 80 ml, 5 giọt nước ép cà độc dược đen, 10 g bột long nha thảo, 3 sợi tóc Naga biển sâu.", "5": "Bậc Thầy Rối Bí Ẩn – Chính: bụi của Oán linh cổ xưa, tinh thể lõi Thạch tượng quỷ sáu cánh. Phụ: 80 ml nước suối vàng đảo Sonia, 10 g vỏ cây long văn, linh tính còn sót của Oán linh cổ xưa, 1 đôi mắt Thạch tượng quỷ sáu cánh. Nghi thức: uống ma dược trong tiếng hát của mỹ nhân ngư.", "4": "Pháp Sư Quỷ Dị – Chính: mắt chính của Tà quái quỷ thuật, linh thể thật của Kẻ cướp linh giới. Phụ: máu Tà quái quỷ thuật 200 ml, 30 g bụi Kẻ cướp linh giới, 10 g vỏ bạch dương lông đỏ, một đoạn dây nho vàng, một mặt nạ cao su tự làm to bằng đầu ngón tay. Nghi thức: dựa chủ yếu vào sức mình, dàn dựng một vở kịch lớn trước nhiều khán giả để mưu sát một bán thần (hoặc sinh vật siêu phàm tương đương), uống ma dược ở đoạn kết vở kịch.", "3": "Học Giả Cổ Đại – Chính: một đôi mắt Chó Fulgrim (kẻ canh giữ Nguyên Bảo), một trái tim hóa bông của Ma lang sương mù. Phụ: máu Chó Fulgrim 100 ml, 30 g tinh thể sương trắng của Ma lang sương mù, lượng lớn ghi chép lịch sử cổ đại chân thực. Nghi thức: hoàn toàn thoát ly hiện thực ít nhất 300 năm, khi bản thân đã thành lịch sử, không còn thuộc thời đại hiện tại thì uống ma dược.", "2": "Kỳ Tích Sư – Chính: tim Ma lang U ám (Thần Ước Nguyện) hoặc đặc tính Kỳ Tích Sư khác. Phụ: 300 ml máu Ma lang U ám, một 'Trùng thời gian', một 'Trùng tinh tú'. Nghi thức: khiến một đoạn lịch sử bị lãng quên trở lại thời đại hiện tại.", "1": "Thị Giả Quỷ Bí – Chính: một phần đặc tính Thị Giả Quỷ Bí. Phụ: chín loại đặc sản Linh giới. Nghi thức: lập một thị trấn toàn bộ là con rối bí ẩn, thiết kế quỹ đạo vận mệnh cho từng con rối, để chúng diễn ra bức tranh đời sống đủ chân thực tới mức Linh giới sinh ra khu vực tương ứng.", "0": "Kẻ Khờ – Chính: Tính duy nhất 'Kẻ Khờ', hai phần đặc tính Thị Giả Quỷ Bí còn lại. Phụ: nắm giữ ít nhất 1/4 Sương mù lịch sử. Nghi thức: lừa dối một lần thời gian, lịch sử hoặc vận mệnh."}}, "cua": {"cong_thuc": {"8": "Bậc Thầy Trò Ảo – Chính: dạ dày Kẻ ăn linh hồn, 20 ml máu cá cờ biển sâu. Phụ: 5 ml tinh dầu cây trăn (鹅耳枥), 10 g bột cỏ cuộn chỉ, 1 bông hoa dẻ đỏ đang nở, nước tinh khiết 80 ml.", "7": "Chiêm Tinh Nhân – Chính: tinh thể vẫn thạch (60 g), kết tinh máu bạch tuộc Lava (bản nâng cấp nguyên liệu của Thầy Bói – chứng tỏ Cửa và Kẻ Khờ có thể hoán đổi ở cấp cao)."}}, "sai_lam": {"cong_thuc": {}}, "khong_tuong": {"cong_thuc": {"9": "Khán Giả – nước tinh khiết 80 ml, 5 giọt tinh chất hoa nghệ thu, 13 g bột thược dược răng trâu, 7 cánh hoa tinh linh, một đôi mắt cá Manhal trưởng thành, 35 ml máu cá đen sừng dê.", "8": "Người Đọc Tâm – Chính: tuyến yên hoàn chỉnh của Á long ảo ảnh (còn gọi Thằn lằn rồng bảy màu), 10 ml dịch tủy sống Thỏ bán u linh (còn gọi thỏ Falsman). Phụ: 5 g bào tử nụ cây dẻ, 8 g bột long nha thảo, 3 cánh hoa tinh linh thuần trắng, 100 ml nước tinh khiết.", "7": "Bác Sĩ Tâm Lý (cổ: Nhà Phân Tích Tinh Thần) – Chính/ phụ gồm: một đôi mắt Kính long, 50 ml máu Kính long, quả của Cây trưởng lão.", "6": "Nhà Thôi Miên – Chính: tuyến yên hoàn chỉnh của Tâm linh cự long thanh niên; hoặc 60 ml dịch tủy sống Cự tích săn đen + 1 quả Cây chuông gió ảo mộng.", "5": "Kẻ Du Mộng – Chính: tim Kẻ bắt mộng + tinh thể Ảo ảnh tâm linh, hoặc bộ não hoàn chỉnh của một Tâm linh cự long trưởng thành. Nghi thức: tìm Yêu điểu đầu người ở Linh giới, ký khế ước, cầm một chiếc lông đuôi của nó rồi uống ma dược trong cảm xúc mãnh liệt (vui sướng hoặc phẫn nộ) – để có lực kéo mình tỉnh khỏi giấc mộng.", "4": "Kẻ Thao Túng – Chính: bộ não hoàn chỉnh của Tâm linh cự long già, hoặc tim kết tinh của Thụ nhân đạo sư, hoặc đặc tính Kẻ Thao Túng. Phụ: 80 ml máu Tâm linh cự long già, 3 lá vàng của Thụ nhân đạo sư, bảy giọt nước mắt của bảy người/ sinh vật dạng người khác nhau sinh ra từ cảm xúc mãnh liệt. Nghi thức: uống ma dược giữa sự cộng hưởng cảm xúc to lớn của ít nhất một vạn người."}}, "mat_troi": {"cong_thuc": {"9": "Người Ca Tụng – Chính: một đóa hoa hướng dương kết tinh, HOẶC lông đuôi của Chim đá lửa/ Chim phóng hỏa trưởng thành; một viên Đá hải yêu HOẶC một đóa Hướng dương ca hát. Phụ: một nhánh cỏ giữa hè, 5 giọt dịch rượu tháng Bảy, một lá Ám diệp tinh linh.", "8": "Người Cầu Quang – Chính: một viên Đá quang huy HOẶC bột Linh hồn trắng rực; máu Nhím gương HOẶC tim Cự quái dung nham. Phụ: một đóa hoa hướng dương viền vàng, 3 giọt dịch phụ tử...", "7": "Thần Quan Mặt Trời – Chính: mào đỏ của Gà trống bình minh, một quả cây Khế linh quang huy. Phụ: 100 ml máu Gà trống bình minh, 10 giọt tinh dầu 'Mặt Trời', 8 g bột kim thủ cam, 5 g dung nham đông đặc.", "6": "Công Chứng Viên – Chính: 1 phần kết tinh rễ Cây trưởng giả, 5 lông đuôi Chim khế linh. Phụ: 100 ml dịch cây Khế linh quang huy, 1 đóa hướng dương viền vàng, 1 đóa hướng dương viền trắng, 5 giọt dịch dương xỉ nước.", "5": "Tư Tế Ánh Sáng – Chính: mào đỏ của Vua gà trống bình minh, một khối Đá quang huy thuần trắng. Phụ: 5 g hương thảo, 7 giọt nước kim thủ cam, 10 ml nước đá, 60 ml máu Vua gà trống bình minh. Nghi thức: trong bóng tối tuyệt đối, vùi toàn thân vào khối băng không tan bình thường rồi uống ma dược.", "4": "Kẻ Vô Ám – Chính: một giọt thần huyết 'Mặt Trời', hoặc ba lông đuôi Thái dương thần điểu trưởng thành + một khối Đá quang huy thần thánh. Phụ: 60 ml máu Thái dương thần điểu, 30 ml dịch cộng sinh Đá quang huy thần thánh, 7 giọt nước kim thủ cam biến dị, 10 g bột Tim dung nham. Nghi thức: tách ra thứ tình cảm mãnh liệt nhất, không muốn từ bỏ nhất, rồi uống ma dược và truyền ngược tình cảm ấy vào trong quá trình."}}, "bao_chua": {"cong_thuc": {"6": "Kẻ Được Gió Ưu Ái – Chính: sáu lông vũ kết tinh của Chim cắt bóng xanh, một đôi mắt Hải điêu long nhãn.", "4": "Chủ Tế Tai Ương – nghi thức rất nguy hiểm: phải uống ma dược giữa động đất và sóng thần (tự gây ra hoặc tìm tới), chống chịu tới khi kết thúc."}}, "thap_trang": {"cong_thuc": {}}, "nguoi_treo_nguoc": {"cong_thuc": {}}, "hac_am": {"cong_thuc": {}}, "tu_than": {"cong_thuc": {}}, "nguoi_khong_lo": {"cong_thuc": {}}, "hong_te_ti": {"cong_thuc": {}}, "ma_nu": {"cong_thuc": {"7": "Phù Thủy – Chính: toàn bộ máu của Ma ngư hắc uyên, trứng Khổng tước mã não. Phụ: nước tinh khiết 80 ml, 5 giọt nước cà độc dược vàng, 3 vảy Thằn lằn bóng tối, 10 giọt nước hoa thủy tiên.", "6": "Ma Nữ Hoan Lạc – Chính: một đôi mắt Nữ yêu mị dục, tuyến tơ của Nhện góa phụ khổng lồ trưởng thành. Phụ: nước tinh khiết 100 ml, 5 giọt nước cà độc dược đen, toàn bộ lông tóc còn lại của Nữ yêu mị dục, 10 g bột ruồi Feynapotter, 5 g tro xác ướp thật."}}, "mau_than": {"cong_thuc": {}}, "mat_trang": {"cong_thuc": {"9": "Dược Sư – Chính: sừng của Phi mã một sừng trưởng thành, 3 g kết tinh nọc Sứa vương miện... (phụ liệu theo bản của giáo hội Mẫu Thần)."}}, "tham_phan": {"cong_thuc": {}}, "hac_hoang_de": {"cong_thuc": {"8": "Kẻ Man Rợ – Chính: một cây Cuồng hóa thảo, tinh thể sừng đặc của Tê giác đại địa. Phụ: một quả óc chó vân sâu, một cây hương phong thảo, 10 ml nước cất ngâm vỏ dương, 100 ml rượu mạnh.", "7": "Kẻ Hối Lộ – Chính: một đóa hoa 'Trẻ sơ sinh khóc', kết tinh Cần sa mặt quỷ. Phụ: 5 giọt nước cà độc dược vàng, 5 giọt nước cà độc dược đen, 4 giọt tinh dầu cỏ ảo mộng, 80 ml rượu vang đỏ."}}, "an_gia": {"cong_thuc": {}}, "hoan_my": {"cong_thuc": {}}, "bi_troi": {"cong_thuc": {}}, "banh_xe": {"cong_thuc": {}}, "vuc_tham": {"cong_thuc": {}}};
