 $id('pwList').innerHTML=h;Array.prototype.forEach.call($id('pwList').querySelectorAll('.card'),function(c){c.onclick=function(){S.pw=c.dataset.v||null;if(S.pw&&S.seq<SEQ_MAX[S.diff])S.seq=SEQ_MAX[S.diff];if(!S.pw)S.seq=9;renderPw();renderAttrs();updPts();};});
 var p=pwObj(),info='';
