 else{var mx=SEQ_MAX[S.diff];var opt='';[9,8,7,6,5].forEach(function(n){opt+='<option value="'+n+'"'+(n===S.seq?' selected':'')+(n<mx?' disabled':'')+'>Danh sách '+n+' – '+esc(p.seq[9-n][0])+' ('+SEQ_COST[n]+' điểm)'+(n<mx?' – khóa ở độ khó này':'')+'</option>';});
  var lad='';p.seq.forEach(function(s,i){var n=9-i;if(n>=5)lad+='<span class="'+(n===S.seq?'cur':'')+'">'+n+'. '+esc(s[0])+'</span>';});lad+='<span>4–0: ??? (bị che khuất)</span>';
  info='<div class="t" style="font-family:Cormorant Garamond,serif;font-size:1.25em;color:'+p.mau+'">Con đường '+esc(p.ten)+' <span class="hint">('+esc(p.hv)+' · '+esc(p.en)+')</span></div><div class="ladder">'+lad+'</div>'+
  '<div style="margin-top:8px"><label class="f">Danh sách khởi đầu</label><select id="seqSel">'+opt+'</select></div>'+
  '<div style="margin-top:8px"><b>Năng lực Danh sách '+S.seq+':</b> '+esc(p.seq[9-S.seq][4])+'</div>'+
