 var nl={};if(p){for(var n=9;n>=ds;n--){var s=p.seq[9-n];nl[key(s[0])]={'Mô_tả':s[4],'Thuần_thục':n===ds?'Sơ bộ':'Thuần thục'};}}
 var tdo='Phàm nhân';if(p){tdo=ds>=8?'Người mới vào nghề':(ds>=6?'Người trong nghề':'Cao thâm');}else if(S.bg==='Nhà thần bí học nghiệp dư'||S.org!=='Không'&&S.org!=='Hải tặc')tdo='Người mới vào nghề';
 var ct={};if(p){var fx=(PWX[p.id]||{}).cong_thuc||{};if(fx[String(ds)])ct[key(p.seq[9-ds][0])]=fx[String(ds)];}
 if(S.gifts.indexOf('Công thức bí truyền')>=0){var gp=$id('giftFormulaPw').value;var gpo=PW.filter(function(x){return x.id===gp;})[0];if(gpo){var gfx=(PWX[gpo.id]||{}).cong_thuc||{};ct[key(gpo.seq[0][0])]=gfx['9']||('Công thức '+gpo.seq[0][0]+' (người kể xác định chi tiết nguyên liệu khi cần).');}}
 var bm={};if(S.gifts.indexOf('Phương pháp sắm vai')>=0)bm['Phương_pháp_sắm_vai']='Tên ma dược là vai diễn – sắm vai đúng nguyên tắc để tiêu hóa ma dược nhanh và an toàn.';
