// cắt phần JSON bị đứt (hết token) về thành viên trọn vẹn cuối cùng rồi đóng ngoặc
function closeJson(t){var st=[],inS=false,bs=false,cut=-1,keep=[];
 for(var i=0;i<t.length;i++){var ch=t[i];
  if(inS){if(bs)bs=false;else if(ch==='\\')bs=true;else if(ch==='"')inS=false;continue;}
  if(ch==='"')inS=true;else if(ch==='{')st.push('}');else if(ch==='[')st.push(']');else if(ch==='}'||ch===']')st.pop();else if(ch===','){cut=i;keep=st.slice();}}
 if(!st.length)return t;if(cut<0)throw new Error('AI trả về JSON bị cắt quá sớm.');return t.slice(0,cut)+keep.reverse().join('');}
function aiJson(raw){var t=String(raw||'').replace(/<think>[\s\S]*?<\/think>/gi,'').replace(/`{3}(?:json)?/gi,'');var a=t.indexOf('{');if(a<0)throw new Error('AI không trả về JSON. Hãy thử lại hoặc đổi mô hình.');
 var b=t.lastIndexOf('}');var body=b>a?t.slice(a,b+1):t.slice(a);
 try{return JSON.parse(body);}catch(e){}
 var fix=t.slice(a).replace(/[\u0000-\u001f]+/g,' ').replace(/[“”]/g,'"').replace(/,\s*([}\]])/g,function(m,c){return c;});
 try{var e2=fix.lastIndexOf('}');return JSON.parse(e2>0?fix.slice(0,e2+1):fix);}catch(e){}
 try{return JSON.parse(closeJson(fix));}catch(e){throw new Error('AI trả về JSON hỏng hoặc bị cắt. Hãy thử lại; nếu lặp lại, tăng độ dài phản hồi tối đa của API hoặc đổi mô hình.');}}

