function pick(list,v,f){v=tx(v,120);if(!v)return null;var lv=lo(v),i,x;f=f||function(y){return y;};
 for(i=0;i<list.length;i++)if(f(list[i])===v)return list[i];
 for(i=0;i<list.length;i++)if(lo(f(list[i]))===lv)return list[i];
 for(i=0;i<list.length;i++){x=lo(f(list[i]));if(x&&lv&&(x.indexOf(lv)===0||lv.indexOf(x)===0))return list[i];}return null;}
// vượt quỹ: giữ "chất" nhân vật (con đường, kim thủ chỉ) lâu nhất, cắt thuộc tính/ kỹ năng dư trước; chỉ cắt các loại có trong cats
function fitPoints(cats){var cut={a:0,k:0,g:[],s:0,p:''};var free=bgObj().sk;var loops=0;function may(c){return cats.indexOf(c)>=0;}
 function attrDown(min){if(!may('a'))return false;var hi=ATTRS[0][0];ATTRS.forEach(function(a){if(S.attrs[a[0]]>S.attrs[hi])hi=a[0];});if(S.attrs[hi]<=min)return false;S.attrs[hi]--;cut.a++;return true;}
 function skillDown(minLv){if(!may('k'))return false;var sk=null,best=0;for(var k in S.skills){var c=LVC[S.skills[k]]-(free[k]?LVC[free[k]]:0);if(c>best&&LV.indexOf(S.skills[k])>minLv){best=c;sk=k;}}if(!sk)return false;
  var nl=LV[LV.indexOf(S.skills[sk])-1];if(free[sk]&&LV.indexOf(nl)<LV.indexOf(free[sk]))nl=free[sk];if(nl)S.skills[sk]=nl;else delete S.skills[sk];cut.k++;return true;}
 while(left()<0&&loops++<300){
  if(attrDown(7)||skillDown(1)||attrDown(5)||skillDown(0))continue;
  if(may('g')&&S.gifts.length){cut.g.push(S.gifts.pop());continue;}
  if(may('s')&&S.pw&&S.seq<9){S.seq++;cut.s++;continue;}
  if(may('p')&&S.pw){cut.p=pwObj().ten;S.pw=null;S.seq=9;continue;}
  if(!attrDown(3))break;}
 var m=[];if(cut.a)m.push('giảm '+cut.a+' bậc thuộc tính');if(cut.k)m.push('hạ '+cut.k+' bậc kỹ năng');if(cut.g.length)m.push('bỏ kim thủ chỉ '+cut.g.join(', '));if(cut.s)m.push('lùi Danh sách '+cut.s+' bậc');if(cut.p)m.push('bỏ con đường '+cut.p);
 return (m.length?'AI vượt quỹ – đã '+m.join(', ')+'.':'')+(left()<0?' Điểm vẫn âm ('+left()+') – hãy giảm ở bước khác.':'');}
