 var desc=$id('aiPrompt').value.trim(),sec=AI_SEC[kind]||{};
 AI.busy=true;AI.stop=false;aiBusy(true);var t0=Date.now();aiSay('Màn sương xám đang thì thầm…','','stop');AI.timer=setInterval(function(){AI.span.textContent='Màn sương xám đang thì thầm… '+Math.round((Date.now()-t0)/1000)+' giây';},1000);
