// không dùng AI: bắt các dòng có nhãn (Tuổi:, Ngoại hình:, Appearance:...), phần còn lại đưa vào tiểu sử
var P_LABELS={gt:'giới tính|gender|sex',age:'tuổi|age',look:'ngoại hình|diện mạo|appearance|looks',pers:'tính cách|personality|traits',job:'nghề nghiệp|nghề|occupation|job',goal:'mục tiêu|goals?',bio:'tiểu sử|lý lịch|quá khứ|background|backstory|history'};
function personaField(t,labels){var m=t.match(new RegExp('(?:^|\\n)[ \\t]*[-*•]?[ \\t]*(?:'+labels+')[ \\t]*[:：][ \\t]*([^\\n]+)','iu'));return m?m[1].trim():'';}
function personaRest(t){var re=new RegExp('^[ \\t]*[-*•]?[ \\t]*(?:'+Object.keys(P_LABELS).filter(function(k){return k!=='bio';}).map(function(k){return P_LABELS[k];}).join('|')+')[ \\t]*[:：]','iu');return t.split('\n').filter(function(l){return !re.test(l);}).join('\n').trim();}
function personaQuick(){aiOut($id('aiStatus'));var P=readPersona();var t=$id('aiPersona').value.trim()||P.desc;if(t)$id('aiPersona').value=t;
 if(!t&&!P.name){aiSay('Không đọc được persona – hãy dán nội dung persona vào ô.','bad');return;}
 AI.undo=snap();var got=[];
 if(P.name){$id('ten').value=P.name.slice(0,60);got.push('tên');}
 var gf=personaField(t,P_LABELS.gt),gv='';
 if(gf)gv=/nữ|female|woman|girl/i.test(gf)?'Nữ':(/nam|male|man|boy/i.test(gf)?'Nam':'Khác');
 else{var fem=(t.match(/\b(she|her|hers|woman|girl)\b|cô ấy|cô gái|thiếu nữ|người phụ nữ/gi)||[]).length,mal=(t.match(/\b(he|him|his|man|boy)\b|anh ấy|chàng trai|cậu ấy|người đàn ông/gi)||[]).length;if(fem>mal)gv='Nữ';else if(mal>fem)gv='Nam';}
 if(gv){$id('gt').value=gv;got.push('giới tính');}
 var af=personaField(t,P_LABELS.age),am=(af||t).match(/(\d{1,2})\s*(?:tuổi|years?\s*old)/i)||(af?af.match(/(\d{1,2})/):null);if(am&&+am[1]>=12&&+am[1]<=90){$id('tuoi').value=+am[1];got.push('tuổi');}
 [['ngoaihinh',P_LABELS.look,600,'ngoại hình'],['tinhcach',P_LABELS.pers,300,'tính cách'],['nghe',P_LABELS.job,80,'nghề'],['muctieu',P_LABELS.goal,200,'mục tiêu']].forEach(function(m){var v=personaField(t,m[1]);if(v){$id(m[0]).value=v.slice(0,m[2]);got.push(m[3]);}});
 var bio=personaField(t,P_LABELS.bio)||personaRest(t);if(bio){$id('tieusu').value=bio.slice(0,1500);got.push('tiểu sử');}
 $id('openMsg').dataset.touched='';renderAll();
 var msg='Đã điền từ persona: '+(got.join(', ')||'không có mục nào')+'. Các thuộc tính, con đường và kim thủ chỉ giữ nguyên – hãy kiểm tra bước Thân phận.';
 aiSay(msg,'ok','undo');aiNotice(msg);go(2);}

