"Mỹ Thần","Beauty Goddess"],"seq":[["Dược Sư","Dược Sư","Apothecary","药师","Nhận biết thảo dược, bào chế thuốc, độc dược, thuốc mê; cơ thể kháng độc."],["Người Thuần Thú","Tuần Thú Sư","Beast Tamer","驯兽师","Thuần hóa và giao tiếp với động vật, sức mạnh – tốc độ tăng."],["Ma Cà Rồng","Hấp Huyết Quỷ","Vampire","吸血鬼","Hút máu hồi phục, hóa dơi, móng vuốt, tốc độ – sức mạnh cao, sợ ánh nắng mạnh ở mức nhất định."],["Giáo Sư Ma Dược","Ma Dược Giáo Thụ","Potions Professor","魔药教授","Pha chế ma dược/ dược tề đặc biệt (thuốc tăng cường, thuốc chữa, thuốc gây biến dị)."],["Học Giả Đỏ Thẫm","Thâm Hồng Học Giả","Scarlet Scholar","深红学者","Sức mạnh gắn với ánh trăng đỏ; 'ánh trăng' hồi phục, gần như bất tử dưới trăng."],["Vu Vương","Vu Vương","Shaman King","巫王","Bán thần. Bóng tối vu vương, nguyền rủa, triệu hoán."],["Đại Sư Triệu Hồi","Triệu Hoán Đại Sư","Summoning Master","召唤大师","Mở 'Cửa triệu hoán' gọi sinh vật từ linh giới."],["Người Sáng Sinh","Sáng Sinh Giả","Life-Giver","创生者","Thiên sứ."],["Thần Mỹ Lệ","Mỹ Thần","Beauty Goddess","美神","Thiên sứ cấp cao (vì vậy Huyết tộc chỉ có Nữ Vương)."],["Mặt Trăng","Nguyệt Lượng","Moon","月亮","Chân thần."]],"sam_vai":"Dược Sư: bào chế thuốc, chữa trị. Người Thuần Thú: thuần phục dã thú (và dã tính của bản thân). Ma Cà Rồng: sống như quý tộc huyết tộc – thanh lịch mà khát máu có kiểm soát."},{"id":"tham_phan","ten":"Kẻ Phán Quyết","hv":"Kẻ Phán Quyết","en":"Justiciar","cn":"审判者","nhom":"Trật Tự (Kẻ Phán Quyết – Hắc Hoàng Đế)","mau":"#c9a227","nam_giu":"Hoàng gia Loen (gia tộc Augustus); Cục Tình báo Quân sự 9 (MI9)","alias":["Kẻ Phán Quyết","Justiciar","审判者","Trọng Tài","Trọng Tài Nhân","Arbiter","仲裁人","Cảnh Sát Trưởng","Trị An Quan","Sheriff","治安官","Thẩm Vấn Giả","Interrogator","审讯者","Thẩm Phán","Pháp Quan","Judge","法官","Kỵ Sĩ Trừng Giới","Disciplinary Paladin","惩戒骑士","Pháp Sư Luật Lệnh","Imperative Mage","律令法师","Thợ Săn Hỗn Loạn","Chaos Hunter","混乱猎手","Người Cân Bằng","Balancer","平衡者","Bàn Tay Trật Tự","Hand of Order","秩序之手","Thẩm Phán Giả"],"seq":[["Trọng Tài","Trọng Tài Nhân","Arbiter","仲裁人","Uy nghiêm tự nhiên khiến người khác dễ nghe theo, thể lực tốt, thiên phú hòa giải/ phân xử tranh chấp."],["Cảnh Sát Trưởng","Trị An Quan","Sheriff","治安官","Cảm nhận bất thường trong khu vực mình quản, trực giác truy bắt, thân thể cường hóa."],["Thẩm Vấn Giả","Thẩm Vấn Giả","Interrogator","审讯者","Thẩm vấn khiến kẻ bị hỏi khó nói dối, đòn đánh tinh thần, 'roi tâm linh'."],["Thẩm Phán","Pháp Quan","Judge","法官","Tuyên phán lệnh cấm trong phạm vi ('Cấm chỉ...'), phán quyết có hiệu lực."],["Kỵ Sĩ Trừng Giới","Trừng Giới Kỵ Sĩ","Disciplinary Paladin","惩戒骑士","Lập vùng luật lệ, trừng phạt kẻ vi phạm, sức chiến đấu cao."],["Pháp Sư Luật Lệnh","Luật Lệnh Pháp Sư","Imperative Mage","律令法师","Bán thần. Luật lệnh cưỡng chế quy mô lớn."],["Thợ Săn Hỗn Loạn","Hỗn Loạn Liệp Thủ","Chaos Hunter","混乱猎手","Săn lùng và trấn áp hỗn loạn."],["Người Cân Bằng","Bình Hành Giả","Balancer","平衡者","Thiên sứ – vd. Derrick Augustus (cựu Công tước Nam Wales)."],["Bàn Tay Trật Tự","Trật Tự Chi Thủ","Hand of Order","秩序之手","Thiên sứ cấp cao – vd. William I, 'Người bảo hộ' lập quốc Loen."],["Kẻ Phán Quyết","Kẻ Phán Quyết","Justiciar","审判者","Chân thần."]],"sam_vai":"Trọng Tài: phân xử công bằng tranh chấp. Cảnh Sát Trưởng: giữ trật tự khu vực mình phụ trách. Thẩm Vấn Giả: thẩm vấn tìm ra sự thật."},{"id":"hac_hoang_de","ten":"Hắc Hoàng Đế","hv":"Hắc Hoàng Đế","en":"Black Emperor","cn":"黑皇帝","nhom":"Trật Tự (Thẩm Phán Giả – Hắc Hoàng Đế)","mau":"#2c2c2c","nam_giu":"Hoàng gia Loen (bí mật, George III); di sản Đế quốc Solomon (Kỷ 4)","alias":["Hắc Hoàng Đế","Black Emperor","黑皇帝","Luật Sư","Lawyer","律师","Kẻ Man Rợ","Dã Man Nhân","Barbarian","野蛮人","Kẻ Hối Lộ","Hối Lộ Giả","Briber","贿赂者","Nam Tước Hủ Bại","Hủ Hóa Nam Tước","Baron of Corruption","腐化男爵","Đạo Sư Hỗn Loạn","Mentor of Disorder","混乱导师","Bá Tước Sa Đọa","Đọa Lạc Bá Tước","Earl of the Fallen","堕落伯爵","Pháp Sư Cuồng Loạn","Frenzied Mage","狂乱法师","Công Tước Entropy","Duke of Entropy","熵之公爵","Thân Vương Diệt Trật Tự","Thí Tự Thân Vương","Prince of Abrogation","弑序亲王"],"seq":[["Luật Sư","Luật Sư","Lawyer","律师","Giỏi tìm và lợi dụng sơ hở của quy tắc và điểm yếu đối thủ, khẩu tài và tư duy biện luận xuất sắc."],["Kẻ Man Rợ","Dã Man Nhân","Barbarian","野蛮人","'Vấn đề không giải quyết được bằng luật thì giải quyết bằng sức mạnh' – thể chất mạnh, kháng ảnh hưởng tinh thần cao."],["Kẻ Hối Lộ","Hối Lộ Giả","Briber","贿赂者","'Hối lộ' – trao lợi ích để làm suy yếu, trói buộc, hoặc khiến đối phương kiêu ngạo, thân cận."],["Nam Tước Hủ Bại","Hủ Hóa Nam Tước","Baron of Corruption","腐化男爵","Bẻ cong lời nói/ hành động ('Vặn vẹo'), làm tha hóa lòng người."],["Đạo Sư Hỗn Loạn","Hỗn Loạn Đạo Sư","Mentor of Disorder","混乱导师","Gây hỗn loạn trật tự, bẻ cong quy tắc."],["Bá Tước Sa Đọa","Đọa Lạc Bá Tước","Earl of the Fallen","堕落伯爵","Bán thần."],["Pháp Sư Cuồng Loạn","Cuồng Loạn Pháp Sư","Frenzied Mage","狂乱法师","Gieo cuồng loạn."],["Công Tước Entropy","Thương Chi Công Tước","Duke of Entropy","熵之公爵","Thiên sứ."],["Thân Vương Diệt Trật Tự","Thí Tự Thân Vương","Prince of Abrogation","弑序亲王","Thiên sứ cấp cao."],["Hắc Hoàng Đế","Hắc Hoàng Đế","Black Emperor","黑皇帝","Chân thần. Nghi thức: lập quốc độ riêng, tên gắn với danh hiệu hoàng đế, lập quy tắc nghiêm ngặt trái lẽ thường, xây bí mật 9 lăng mộ kim tự tháp."]],"sam_vai":"Luật Sư: tìm sơ hở trong luật lệ. Kẻ Man Rợ: dùng sức mạnh khi luật lệ bất lực. Kẻ Hối Lộ: dùng lợi ích lay chuyển người khác."},{"id":"an_gia","ten":"Ẩn Sĩ","hv":"Ẩn Sĩ","en":"Hermit","cn":"隐者","nhom":"Tri Thức (Ẩn Sĩ – Người Hoàn Mỹ)","mau":"#6c5ce7","nam_giu":"Mạc Tư Khổ Tu Hội (nguồn gốc); Giáo hội Nữ Thần Hắc Dạ (Danh sách 9); tà thần Ẩn Nặc Hiền Giả","alias":["Ẩn Sĩ","Hermit","隐者","Kẻ Dò Bí Mật","Khuy Bí Nhân","Mystery Pryer","窥秘人","Học Giả Cách Đấu","Cách Đấu Học Giả","Melee Scholar","格斗学者","Vu Sư","Warlock","巫师","Giáo Sư Quyển Trục","Scrolls Professor","卷轴教授","Tinh Tượng Sư","Constellations Master","星象师","Nhà Thần Bí Học","Mysticologist","神秘学家","Đại Sư Tiên Tri","Clairvoyant","预言大师","Hiền Giả","Sage","贤者","Hoàng Đế Tri Thức","Knowledge Emperor","知识皇帝","Ẩn Giả"],"seq":[["Kẻ Dò Bí Mật","Khuy Bí Nhân","Mystery Pryer","窥秘人","Linh thị mạnh, cảm nhận linh tính, học thần bí học nhanh, nghi thức ma pháp cơ bản. Cách ngôn: 'Làm điều mình muốn, nhưng chớ gây hại'."],["Học Giả Cách Đấu","Cách Đấu Học Giả","Melee Scholar","格斗学者","Nghiên cứu kỹ thuật chiến đấu như một môn học, phản xạ và thể chất tăng."],["Vu Sư","Vu Sư","Warlock","巫师","Thi triển nhiều phép thuật tức thời (lửa, băng, gió...), nghi thức ma pháp mạnh hơn."],["Giáo Sư Quyển Trục","Quyển Trục Giáo Thụ","Scrolls Professor","卷轴教授","Chế tác quyển trục lưu trữ phép thuật/ năng lực để dùng sau."],["Tinh Tượng Sư","Tinh Tượng Sư","Constellations Master","星象师","Linh thị toàn cảnh, nhìn thấy các 'tấm màn' tầng tầng lớp lớp, phép thuật tinh tú."],["Nhà Thần Bí Học","Thần Bí Học Gia","Mysticologist","神秘学家","Bán thần. Mô phỏng năng lực phi phàm đã hiểu thấu."],["Đại Sư Tiên Tri","Dự Ngôn Đại Sư","Clairvoyant","预言大师","Tiên tri chính xác."],["Hiền Giả","Hiền Giả","Sage","贤者","Thiên sứ – vd. Bernadette Gustav."],["Hoàng Đế Tri Thức","Tri Thức Hoàng Đế","Knowledge Emperor","知识皇帝","Thiên sứ cấp cao."],["Ẩn Sĩ","Ẩn Sĩ","Hermit","隐者","Chân thần."]],"sam_vai":"Kẻ Dò Bí Mật: tìm hiểu bí ẩn nhưng giữ kính sợ, 'làm điều mình muốn, nhưng chớ gây hại'. Học Giả Cách Đấu: coi chiến đấu là học thuật. Vu Sư: nghiên cứu và thi triển phép thuật."},{"id":"hoan_my","ten":"Người Hoàn Mỹ","hv":"Hoàn Mỹ Giả","en":"Paragon","cn":"完美者","nhom":"Tri Thức (Ẩn Giả – Người Hoàn Mỹ)","mau":"#b87333","nam_giu":"Giáo hội Thần Hơi Nước và Máy Móc (Intis/ Loen); Máy Móc Chi Tâm","alias":["Người Hoàn Mỹ","Hoàn Mỹ Giả","Paragon","完美者","Người Thông Thạo","Thông Thức Giả","Savant","通识者","Nhà Khảo Cổ","Khảo Cổ Học Gia","Archaeologist","考古学家","Giám Định Sư","Appraiser","鉴定师","Thợ Thủ Công","Công Tượng","Artisan","工匠","Nhà Thiên Văn","Thiên Văn Học Gia","Tinh Thuật Sư","Astronomer","天文学家","Nhà Giả Kim","Luyện Kim Thuật Sĩ","Alchemist","炼金