function dcList(){var nv=obj(S['Nhân_vật_chính']);var dc=obj(nv['Di_chứng']);var today=dayIdx(S['Thế_giới']);return Object.keys(dc).map(function(k){var d=obj(dc[k]);var het=num(d['Hết_hạn']);if(het>0&&het<=today)return '';var con=het>0?('còn '+(het-today)+' ngày'):(num(d['Thời_hạn_ngày'])>0?num(d['Thời_hạn_ngày'])+' ngày':'vĩnh viễn');var eff=[];if(num(d['Trần_Lý_trí'],100)<100)eff.push('Lý trí ≤ '+num(d['Trần_Lý_trí'],100));if(num(d['Hệ_số_tiêu_hóa'],1)<1)eff.push('Tiêu hóa ×'+num(d['Hệ_số_tiêu_hóa'],1));if(num(d['Sàn_nguy_cơ'])>0)eff.push('Nguy cơ ≥ '+num(d['Sàn_nguy_cơ']));if(num(d['Giảm_Linh_tính_tối_đa'])>0)eff.push('Linh tính tối đa −'+num(d['Giảm_Linh_tính_tối_đa']));return '<div class="item"><div class="t"><span>'+esc(kn(k))+'</span><span class="chip">'+esc(d['Mức']||'')+' · '+esc(con)+'</span></div><div class="d">'+esc(d['Mô_tả']||'')+'</div>'+(eff.length?'<div class="side">'+esc(eff.join(' · '))+'</div>':'')+'</div>';}).filter(Boolean);}

