import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

/* =====================================================================
 *  QUỶ BÍ CHI CHỦ · ĐỒNG NHÂN — Cấu trúc biến (Zod)
 *  - Trường bắt đầu bằng "_" dùng cho cấu hình và hồ sơ khởi tạo.
 *  - Mọi danh sách động đều là Object (Record), KHÔNG phải mảng.
 *  - Các helper chịu lỗi: AI viết sai kiểu vẫn được ép về đúng kiểu.
 * ===================================================================== */

const Chuoi = (d = '') =>
  z
    .preprocess(v => {
      if (v === null || v === undefined) return d;
      if (typeof v === 'string') return v;
      if (typeof v === 'number' || typeof v === 'boolean') return String(v);
      try { return JSON.stringify(v); } catch (e) { return d; }
    }, z.string())
    .prefault(d);

const So = (d = 0, min = -Infinity, max = Infinity) =>
  z
    .preprocess(v => (v === null || v === undefined || v === '' ? d : v), z.coerce.number().catch(d))
    .transform(v => _.clamp(Number.isFinite(v) ? v : d, min, max))
    .prefault(d);

const Co = (d = false) =>
  z
    .preprocess(v => {
      if (v === null || v === undefined) return d;
      if (typeof v === 'string') return ['true', 'có', 'co', 'yes', '1', 'đúng', 'x'].includes(v.trim().toLowerCase());
      return Boolean(v);
    }, z.boolean())
    .prefault(d);

const Bang = val => z.preprocess(x => (x && typeof x === 'object' && !Array.isArray(x) ? x : {}), z.record(z.string(), val)).prefault({});
/* Cứu nhóm object: AI ghi chuỗi/ mảng vào cả NHÓM → về {} thay vì để parse ném lỗi hủy cả lượt cập nhật.
 * Kèm SỬA KEY GÕ SAI GẦN ĐÚNG: so sánh bỏ dấu (vd 'Siêu_phạm' ≡ 'Siêu_phàm' khi bỏ dấu) — key sai dấu
 * tự ghép về đúng trường thay vì bị gạch bỏ khiến thao tác của AI vô hiệu. */
const boDau = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
const layHinh = schema => {
  const daXem = new Set();
  const tim = s => {
    if (!s || typeof s !== 'object' || daXem.has(s)) return null;
    daXem.add(s);
    try { if (s.shape) return s.shape; } catch (e) {}
    const u = [];
    try { if (s.in) u.push(s.in); } catch (e) {}
    try { if (s.out) u.push(s.out); } catch (e) {}
    const d = s._def || {};
    if (d.innerType) u.push(d.innerType);
    if (d.in) u.push(d.in);
    if (d.out) u.push(d.out);
    if (d.schema) u.push(d.schema);
    for (let i = 0; i < u.length; i++) { const kq = tim(u[i]); if (kq) return kq; }
    return null;
  };
  return tim(schema);
};
const layTruong = schema => { const h = layHinh(schema); return h ? Object.keys(h) : null; };
const tronSau = (thu, nguon, ghiDe) => { if (!nguon || typeof nguon !== 'object' || Array.isArray(nguon)) return; if (!thu || typeof thu !== 'object' || Array.isArray(thu)) return; Object.keys(nguon).forEach(k => { if (!(k in thu)) { thu[k] = nguon[k]; return; } if (ghiDe && typeof nguon[k] === 'string' && nguon[k].trim() !== '' && typeof thu[k] === 'string') { thu[k] = nguon[k]; return; } tronSau(thu[k], nguon[k], ghiDe); }); };
const suaKeyGanDung = (x, hopLe) => {
  if (!hopLe || !x || typeof x !== 'object' || Array.isArray(x)) return;
  const bang = {};
  hopLe.forEach(t => { bang[boDau(t).replace(/[_\s]/g, '').toLowerCase()] = t; });
  Object.keys(x).forEach(k => {
    const t = bang[boDau(k).replace(/[_\s]/g, '').toLowerCase()];
    if (!t || t === k) return;
    if (!(t in x)) { x[t] = x[k]; delete x[k]; return; }
    if (x[t] && typeof x[t] === 'object' && !Array.isArray(x[t]) && x[k] && typeof x[k] === 'object' && !Array.isArray(x[k])) { tronSau(x[t], x[k], true); delete x[k]; return; }
    if (typeof x[k] === 'string' && x[k].trim() !== '' && typeof x[t] === 'string') { x[t] = x[k]; delete x[k]; }
  });
};
const nhomAnToan = schema => {
  const hopLe = layTruong(schema);
  return z.preprocess(x => {
    if (!x || typeof x !== 'object' || Array.isArray(x)) return {};
    suaKeyGanDung(x, hopLe);
    return x;
  }, schema);
};
/* Sửa key gần đúng cho nhóm BẮT BUỘC có dữ liệu (không thay {} khi rác — tránh mất hồ sơ).
 * Kèm CHUYỂN NHÓM BỊ LỒNG NHẦM: AI ghi '/Nhân_vật_chính/Nhiệm_vụ/...' (Nhiệm_vụ là nhóm GỐC) →
 * tự chuyển khối dữ liệu đó về đúng nhóm gốc thay vì bị gạch bỏ. */
const nhomSuaKey = schema => {
  const hinh = layHinh(schema);
  const hopLe = hinh ? Object.keys(hinh) : null;
  const truongCon = {};
  if (hinh && hopLe) hopLe.forEach(g => { truongCon[g] = layTruong(hinh[g]); });
  return z.preprocess(x => {
    if (x && typeof x === 'object' && !Array.isArray(x)) {
      suaKeyGanDung(x, hopLe);
      if (hopLe) {
        const bangNhom = {};
        hopLe.forEach(g => { bangNhom[boDau(g).toLowerCase()] = g; });
        hopLe.forEach(g => {
          const con = x[g];
          if (!con || typeof con !== 'object' || Array.isArray(con)) return;
          if (!truongCon[g]) return;
          Object.keys(con).forEach(k => {
            const t = bangNhom[boDau(k).toLowerCase()];
            if (!t || t === g) return;
            if (truongCon[g] && truongCon[g].indexOf(k) >= 0) return;
            if (!x[t] || typeof x[t] !== 'object' || Array.isArray(x[t])) x[t] = {};
            tronSau(x[t], con[k]);
            delete con[k];
          });
        });
      }
    }
    return x;
  }, schema);
};

/* ---------- Bộ cứu & đồng bộ (PHẢI nằm TRƯỚC mọi schema dùng transform — nếu sau sẽ gãy TDZ khi nạp) ---------- */
const gocDoiTuong = v => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});
const khoaConDuong = s => String(s || '').trim().replace(/\s+/g, '_');
/* Chống ném lỗi: transform gặp dữ liệu lạ chỉ bỏ qua, tuyệt đối không làm Schema.parse ném exception
 * (Schema.parse ném lỗi = toàn bộ lượt cập nhật biến bị hủy, mọi biến "đứng im") */
const anToan = fn => (v, ctx) => { try { return fn(v, ctx); } catch (e) { return v; } };
/* Cứu giá trị: AI ghi chuỗi/ số vào nhóm có cấu trúc object → bọc lại đúng khung thay vì để parse ném lỗi */
const cuoiKhoan = (e, khung) => (e && typeof e === 'object' && !Array.isArray(e) ? e : khung(e));
const bangCuu = (val, khung) =>
  z.preprocess(x => {
    if (!x || typeof x !== 'object' || Array.isArray(x)) return {};
    const out = {};
    Object.keys(x).forEach(k => { out[k] = cuoiKhoan(x[k], khung); });
    return out;
  }, z.record(z.string(), val)).prefault({});

/* ---------- Đồng bộ Siêu_phàm: Các_Con_đường là nguồn dữ liệu chính (mỗi con đường một bản ghi);
 * trường phẳng Danh_sách/ Tên_danh_sách/ Độ_tiêu_hóa... chỉ là PHẢN CHIẾU của con đường đang hoạt động.
 * Dữ liệu cũ (chưa có Các_Con_đường) được tự chuyển đổi thành bản ghi một lần duy nhất. ---------- */
const dongBoSieuPham = sp => {
  const rec0 = gocDoiTuong(sp['Các_Con_đường']);
  const rec = {};
  Object.keys(rec0).forEach(k => {
    const nk = khoaConDuong(k);
    const e = gocDoiTuong(rec0[nk] || rec0[k]);
    if (!String(e['Tên'] || '').trim()) e['Tên'] = String(nk).replace(/_/g, ' ');
    rec[nk] = e;
  });
  const cur = String(sp['Con_đường'] || '').trim();
  if (!cur || cur === 'Chưa có') return { ...sp, Các_Con_đường: rec };
  let key = rec[cur] ? cur : khoaConDuong(cur);
  if (!rec[key]) {
    const found = Object.keys(rec).find(k => String(gocDoiTuong(rec[k])['Tên'] || '').trim() === cur);
    if (found) key = found;
  }
  if (!rec[key]) {
    if (!Object.keys(rec).length) {
      // Dữ liệu cũ (chưa từng có bản ghi): tạo bản ghi đầu tiên từ trường phẳng
      rec[key] = {
        Tên: cur,
        Nhóm: '',
        Danh_sách: sp['Danh_sách'],
        Tên_danh_sách: sp['Tên_danh_sách'],
        Độ_tiêu_hóa: sp['Độ_tiêu_hóa'],
        Mục_tiêu_thăng_cấp: sp['Mục_tiêu_thăng_cấp'],
        Thang: {},
        Nguyên_tắc_sắm_vai: gocDoiTuong(sp['Nguyên_tắc_sắm_vai']),
        Năng_lực: gocDoiTuong(sp['Năng_lực']),
      };
    } else {
      // Con trỏ không khớp bản ghi nào (AI ghi nhầm/ quên insert): KHÔNG tự bịa dữ liệu,
      // giữ nguyên các bản ghi và trường phẳng, chờ lượt sau được sửa
      return { ...sp, Các_Con_đường: rec };
    }
  }
  const e = gocDoiTuong(rec[key]);
  return {
    ...sp,
    Các_Con_đường: rec,
    Danh_sách: e['Danh_sách'],
    Tên_danh_sách: String(e['Tên_danh_sách'] || '') || 'Phàm nhân',
    Độ_tiêu_hóa: e['Độ_tiêu_hóa'],
    Mục_tiêu_thăng_cấp: String(e['Mục_tiêu_thăng_cấp'] || '') || 'Chưa xác định',
    Nguyên_tắc_sắm_vai: gocDoiTuong(e['Nguyên_tắc_sắm_vai']),
    Năng_lực: gocDoiTuong(e['Năng_lực']),
  };
};

/* ---------- Đồng bộ NPC: Các_Con_đường {tên con đường: 'số – tên danh sách'} là nguồn chính
 * (NPC có thể sở hữu nhiều con đường, ghi theo mức MC biết);
 * Con_đường/ Danh_sách là phản chiếu của con đường được biết đến ĐẦU TIÊN. Dữ liệu cũ tự chuyển đổi. ---------- */
const dongBoNpc = nv => {
  const rec0 = gocDoiTuong(nv['Các_Con_đường']);
  const rec = {};
  Object.keys(rec0).forEach(k => {
    const nk = khoaConDuong(k);
    if (!(nk in rec)) rec[nk] = String(rec0[nk] !== undefined ? rec0[nk] : rec0[k]).trim() || 'Chưa rõ';
  });
  const cd = String(nv['Con_đường'] || '').trim();
  if (!Object.keys(rec).length && cd && cd !== 'Chưa rõ') {
    rec[khoaConDuong(cd)] = String(nv['Danh_sách'] || '').trim() || 'Chưa rõ';
  }
  const ks = Object.keys(rec);
  if (!ks.length) return { ...nv, Các_Con_đường: rec };
  return {
    ...nv,
    Các_Con_đường: rec,
    Con_đường: String(ks[0]).replace(/_/g, ' '),
    Danh_sách: rec[ks[0]],
  };
};

/* ---------- Tiền tệ Loen: 1 Bảng = 20 Soli, 1 Soli = 12 Penny ---------- */
const TaiSan = z
  .object({
    Bảng: So(0, -1e9, 1e9),
    Soli: So(0, -1e9, 1e9),
    Penny: So(0, -1e9, 1e9),
    Tiền_khác: Bang(So(0, 0, 1e12)),
    Bất_động_sản: Chuoi('Không có'),
  })
  .transform(anToan(t => {
    // Chuẩn hóa: quy toàn bộ về penny rồi chia lại (tự xử lý số lẻ và số âm do AI trừ tiền)
    let tong = Math.round(t.Bảng * 240 + t.Soli * 12 + t.Penny);
    if (!Number.isFinite(tong) || tong < 0) tong = 0;
    const bang = Math.floor(tong / 240);
    const soli = Math.floor((tong % 240) / 12);
    const penny = tong % 12;
    return { ...t, Bảng: bang, Soli: soli, Penny: penny };
  }))
  .prefault({});

const NangLuc = z
  .object({
    Mô_tả: Chuoi(''),
    Thuần_thục: Chuoi('Sơ bộ'),
  })
  .prefault({});

const VatPhamThanBi = z
  .object({
    Phân_loại: Chuoi('Vật phẩm thần kỳ'),
    Năng_lực: Chuoi(''),
    Tác_dụng_phụ: Chuoi('Chưa rõ'),
    Ghi_chú: Chuoi(''),
  })
  .prefault({});

const VatPham = z
  .object({
    Số_lượng: So(1, 0, 1e9),
    Mô_tả: Chuoi(''),
  })
  .prefault({});

const NPC = z
  .object({
    Thân_phận: Chuoi('Chưa rõ'),
    Con_đường: Chuoi('Chưa rõ'),
    Danh_sách: Chuoi('Chưa rõ'),
    Các_Con_đường: Bang(Chuoi('Chưa rõ')),
    Hảo_cảm: So(0, -100, 100),
    Tin_tưởng: So(0, 0, 100),
    Quan_hệ: Chuoi('Người lạ'),
    Trạng_thái: Chuoi('Còn sống'),
    Vị_trí: Chuoi('Chưa rõ'),
    Có_mặt: Co(false),
    Ấn_tượng: Chuoi(''),
    Tri_thức: Bang(Chuoi('')),
  })
  .transform(anToan(dongBoNpc))
  .prefault({});

const ToChuc = z
  .object({
    Quan_hệ: Chuoi('Trung lập'),
    Chức_vị: Chuoi('Không'),
    Uy_tín: So(0, -100, 100),
    Ghi_chú: Chuoi(''),
  })
  .prefault({});

const NhiemVu = z
  .object({
    Nguồn: Chuoi('Tự đặt'),
    Mục_tiêu: Chuoi(''),
    Tiến_độ: Chuoi('Mới bắt đầu'),
    Phần_thưởng: Chuoi('Chưa rõ'),
    Trạng_thái: Chuoi('Đang tiến hành'),
  })
  .prefault({});

/* ---------- Một Con đường MC sở hữu: key = tên con đường bỏ khoảng trắng, Tên = tên hiển thị có khoảng trắng ---------- */
const ConDuong = z
  .object({
    Tên: Chuoi(''),
    Nhóm: Chuoi(''),
    Danh_sách: So(9, 0, 10),
    Tên_danh_sách: Chuoi(''),
    Độ_tiêu_hóa: So(0, 0, 100),
    Mục_tiêu_thăng_cấp: Chuoi('Chưa xác định'),
    Thang: Bang(Chuoi('')),
    Nguyên_tắc_sắm_vai: Bang(Chuoi('')),
    Năng_lực: bangCuu(NangLuc, s => ({ Mô_tả: String(s ?? '') })),
